import { NativeTabs } from "expo-router/native-tabs";
import { useColors } from "@/lib/ui";

// Native tab bar: on iOS 26 and later the system draws it in Liquid Glass over the content.
// Adding a tab is a `platform` issue.
export default function TabsLayout() {
  const colors = useColors();
  return (
    <NativeTabs tintColor={colors.accent}>
      <NativeTabs.Trigger name="index">
        <NativeTabs.Trigger.Label>Map</NativeTabs.Trigger.Label>
        <NativeTabs.Trigger.Icon sf={{ default: "map", selected: "map.fill" }} />
      </NativeTabs.Trigger>
      <NativeTabs.Trigger name="night">
        <NativeTabs.Trigger.Label>Night</NativeTabs.Trigger.Label>
        <NativeTabs.Trigger.Icon sf={{ default: "moon.zzz", selected: "moon.zzz.fill" }} />
      </NativeTabs.Trigger>
      <NativeTabs.Trigger name="stays">
        <NativeTabs.Trigger.Label>Stays</NativeTabs.Trigger.Label>
        <NativeTabs.Trigger.Icon sf={{ default: "bed.double", selected: "bed.double.fill" }} />
      </NativeTabs.Trigger>
      <NativeTabs.Trigger name="account">
        <NativeTabs.Trigger.Label>Account</NativeTabs.Trigger.Label>
        <NativeTabs.Trigger.Icon
          sf={{ default: "person.crop.circle", selected: "person.crop.circle.fill" }}
        />
      </NativeTabs.Trigger>
    </NativeTabs>
  );
}

